// Monta o pedido para a API da Anthropic a partir do contexto enviado pelo CRM
const b = $input.first().json.body;
const conversa = (b.messages || [])
  .map(m => `[${m.from === 'cliente' ? 'Cliente' : 'Corretor'} ${m.at.slice(0, 16).replace('T', ' ')}] ${m.text}`)
  .join('
');

const request = {
  max_tokens: 800,
  system: "Você é o assistente interno da Norden Imóveis, imobiliária de alto padrão em Jurerê Internacional e região (Florianópolis/SC).
Você NÃO fala com o cliente. Você ajuda o corretor a entender a conversa e sugere uma resposta que ele vai revisar antes de enviar.

Tom da Norden ("Concierge"): elegante, consultivo, acolhedor, sem pressão de vendas, sem gírias, sem excesso de emojis, frases curtas adequadas ao WhatsApp. Nunca invente preços, disponibilidade, metragens ou condições; se o cliente pedir algo que exige dado concreto, sugira que o corretor confirme e retorne.

Classifique a temperatura do lead:
- QUENTE: demonstra intenção clara e próxima (quer visitar, pergunta condições, tem orçamento/prazo definidos).
- MORNO: interesse real, mas ainda explorando ou sem prazo.
- FRIO: pouco engajamento, curiosidade, ou sinal de que não é o momento.
- NAO_AVALIADO: informação insuficiente.

Responda SOMENTE com um JSON válido, sem markdown, no formato:
{"summary": "até 3 frases sobre o que o cliente busca e o estágio da conversa", "suggestedTemperature": "QUENTE|MORNO|FRIO|NAO_AVALIADO", "draftReply": "mensagem sugerida para o corretor enviar, assinando com o primeiro nome dele"}",
  messages: [{
    role: 'user',
    content: `Dados do lead: ${JSON.stringify(b.lead)}
Corretor responsável: ${b.broker?.name}

Conversa (mais recente por último):
${conversa}`,
  }],
};
return [{ json: { leadId: b.leadId, request } }];

// Extrai o JSON devolvido pelo Claude
const leadId = $('Montar pedido').first().json.leadId;
const text = ($input.first().json.content || [])
  .filter(c => c.type === 'text')
  .map(c => c.text)
  .join('')
  .replace(/```json|```/g, '')
  .trim();

let data;
try {
  data = JSON.parse(text);
} catch (e) {
  data = { summary: text.slice(0, 500), suggestedTemperature: 'NAO_AVALIADO', draftReply: '' };
}
const temps = ['QUENTE', 'MORNO', 'FRIO', 'NAO_AVALIADO'];
return [{ json: {
  leadId,
  summary: String(data.summary || '').slice(0, 2000),
  suggestedTemperature: temps.includes(data.suggestedTemperature) ? data.suggestedTemperature : 'NAO_AVALIADO',
  draftReply: String(data.draftReply || '').slice(0, 4000),
} }];
